import React, { useState, useEffect } from 'react';
import { Container, Typography, Paper, TextField, Button, Box, Alert } from '@mui/material';
import { useAuth } from '../context/AuthContext';
import axios from 'axios';

const Profile = () => {
  const { currentUser } = useAuth();
  const [profile, setProfile] = useState({});
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    if (currentUser) {
      setProfile(currentUser.profile || {});
    }
  }, [currentUser]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      await axios.put('http://localhost:5000/api/auth/profile', profile);
      setMessage('Profile updated successfully!');
    } catch (error) {
      setMessage('Error updating profile: ' + error.response?.data?.error);
    } finally {
      setLoading(false);
    }
  };

  if (!currentUser) {
    return (
      <Container>
        <Typography>Please log in to view profile</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Paper sx={{ p: 3 }}>
        <Typography variant="h4" gutterBottom>
          Profile
        </Typography>
        
        {message && (
          <Alert severity={message.includes('Error') ? 'error' : 'success'} sx={{ mb: 2 }}>
            {message}
          </Alert>
        )}

        <form onSubmit={handleSubmit}>
          {currentUser.role === 'student' && (
            <>
              <TextField
                fullWidth
                label="First Name"
                value={profile.personalInfo?.firstName || ''}
                onChange={(e) => setProfile(prev => ({
                  ...prev,
                  personalInfo: { ...prev.personalInfo, firstName: e.target.value }
                }))}
                margin="normal"
              />
              <TextField
                fullWidth
                label="Last Name"
                value={profile.personalInfo?.lastName || ''}
                onChange={(e) => setProfile(prev => ({
                  ...prev,
                  personalInfo: { ...prev.personalInfo, lastName: e.target.value }
                }))}
                margin="normal"
              />
            </>
          )}

          {currentUser.role === 'institution' && (
            <>
              <TextField
                fullWidth
                label="Institution Name"
                value={profile.name || ''}
                onChange={(e) => setProfile(prev => ({ ...prev, name: e.target.value }))}
                margin="normal"
              />
              <TextField
                fullWidth
                label="Phone"
                value={profile.phone || ''}
                onChange={(e) => setProfile(prev => ({ ...prev, phone: e.target.value }))}
                margin="normal"
              />
            </>
          )}

          {currentUser.role === 'company' && (
            <>
              <TextField
                fullWidth
                label="Company Name"
                value={profile.name || ''}
                onChange={(e) => setProfile(prev => ({ ...prev, name: e.target.value }))}
                margin="normal"
              />
              <TextField
                fullWidth
                label="Industry"
                value={profile.industry || ''}
                onChange={(e) => setProfile(prev => ({ ...prev, industry: e.target.value }))}
                margin="normal"
              />
            </>
          )}

          <Button
            type="submit"
            variant="contained"
            sx={{ mt: 3 }}
            disabled={loading}
          >
            {loading ? 'Updating...' : 'Update Profile'}
          </Button>
        </form>
      </Paper>
    </Container>
  );
};

export default Profile;
